.venv/bin/python - <<'PY'
import json,re,statistics,time,urllib.request
import serial
p='/dev/cu.usbserial-1130'
h=serial.Serial(p,115200,timeout=0.1,write_timeout=1); h.dtr=False; h.rts=False
start=time.monotonic(); end=start+105; raw=bytearray(); sent=set()
schedule=[(18,b'status\n','s18'),(50,b'status\n','s50'),(92,b'status\n','s92')]
while time.monotonic()<end:
    elapsed=time.monotonic()-start
    for at,cmd,name in schedule:
        if elapsed>=at and name not in sent:
            h.write(cmd); h.flush(); sent.add(name)
    n=h.in_waiting
    if n: raw.extend(h.read(n))
    time.sleep(0.05)
time.sleep(1); n=h.in_waiting
if n: raw.extend(h.read(n))
h.close(); text=raw.decode(errors='replace')
print('STAGE28E_E3_HW_SERIAL_CHARS',len(text)); print(text[-50000:])
if 'queue_psram=1 queue_bytes=4736' not in text: raise SystemExit('telemetry queue PSRAM path missing')
status=[]
for line in text.splitlines():
    if not line.startswith('status firmware_sha='): continue
    d=dict(re.findall(r'([A-Za-z0-9_]+)=([^ ]+)',line))
    if d.get('firmware_sha')!='4a8ce18edd8cc90e6300929d2d9f035c4ec49eb5': raise SystemExit('unexpected firmware sha')
    if d.get('outputs')!='fake-locked' or d.get('rf_ready')!='0': raise SystemExit('unsafe output mode')
    status.append(d)
if len(status)<3: raise SystemExit(f'need >=3 status samples, got {len(status)}')
main=[]; store=[]
for line in text.splitlines():
    if line.startswith('task name=main '):
        d=dict(re.findall(r'([A-Za-z0-9_]+)=([^ ]+)',line)); main.append(d)
    elif line.startswith('task name=stage27_store '):
        d=dict(re.findall(r'([A-Za-z0-9_]+)=([^ ]+)',line)); store.append(d)
if len(main)<3: raise SystemExit(f'need >=3 main task samples, got {len(main)}')
if len(store)<3: raise SystemExit(f'need >=3 stage27_store samples, got {len(store)}')
for d in main:
    if int(d.get('configured_stack_bytes','0'))!=12288: raise SystemExit('wrong main configured stack')
    if int(d.get('hwm_bytes','0'))<4096: raise SystemExit('main stack HWM margin too small')
for d in store:
    if int(d.get('configured_stack_bytes','0'))!=6144: raise SystemExit('wrong stage27_store configured stack')
    if int(d.get('hwm_bytes','0'))<1536: raise SystemExit('stage27_store HWM margin too small')
soak=[]
for line in text.splitlines():
    if 'soak_v=2 firmware_sha=4a8ce18edd8cc90e6300929d2d9f035c4ec49eb5' not in line: continue
    d=dict(re.findall(r'([A-Za-z0-9_]+)=([^ ]+)',line))
    if 'storage_queue_drops' not in d: continue
    if int(d.get('storage_queue_drops','-1'))!=0: raise SystemExit('storage queue drops detected')
    if int(d.get('storage_write_errors','-1'))!=0: raise SystemExit('storage write errors detected')
    if d.get('outputs')!='fake-locked': raise SystemExit('unsafe soak output mode')
    soak.append(d)
if len(soak)<9: raise SystemExit(f'need >=9 soak samples, got {len(soak)}')
for d in status:
    if int(d['internal_free'])<223000: raise SystemExit('internal free did not show expected E3 gain')
    if int(d['internal_min'])<222400: raise SystemExit('internal min did not show expected E3 gain')
    if int(d['internal_largest'])<176128: raise SystemExit('largest internal block regressed')
if int(soak[-1].get('storage_records_written','0'))<10: raise SystemExit('insufficient storage writes')
heartbeats=text.count('heartbeat seq='); heap_ok=text.count('heap_integrity_ok check=')
if heartbeats<9: raise SystemExit(f'insufficient heartbeats {heartbeats}')
if heap_ok<1: raise SystemExit(f'insufficient heap checks {heap_ok}')
for bad in ['heap_integrity_failed','arbiter_counter_regression','Guru Meditation Error','CORRUPT HEAP','Stack canary watchpoint triggered','stage28e_coredump present=1 valid=1']:
    if bad in text: raise SystemExit('unexpected fault '+bad)
vals=[]; outputs=[]
for _ in range(5):
    with urllib.request.urlopen('http://192.168.0.16/rpc/Switch.GetStatus?id=0',timeout=5) as resp: d=json.load(resp)
    vals.append(float(d.get('apower',0.0))); outputs.append(bool(d.get('output',False))); time.sleep(0.4)
med=statistics.median(vals)
last=status[-1]; main_worst=min(int(x['hwm_bytes']) for x in main); store_worst=min(int(x['hwm_bytes']) for x in store)
print('STAGE28E_E3_HW_INTERNAL free=%s min=%s largest=%s gain_free_vs_e2=%d gain_min_vs_e2=%d'%(last['internal_free'],last['internal_min'],last['internal_largest'],int(last['internal_free'])-219568,int(last['internal_min'])-219036))
print('STAGE28E_E3_HW_MAIN configured=12288 worst_hwm=%d'%main_worst)
print('STAGE28E_E3_HW_STAGE27_STORE configured=6144 worst_hwm=%d'%store_worst)
print('STAGE28E_E3_HW_STORAGE written=%s drops=%s write_errors=%s'%(soak[-1]['storage_records_written'],soak[-1]['storage_queue_drops'],soak[-1]['storage_write_errors']))
print('STAGE28E_E3_HW_HEARTBEATS',heartbeats,'HEAP_OK',heap_ok)
print('STAGE28E_E3_HW_SHELLY output_all_on=%d median_apower_w=%.2f samples=%s'%(all(outputs),med,vals))
if not all(outputs) or not (45.0<=med<=80.0): raise SystemExit('Shelly safety check failed')
print('STAGE28E_E3_MAIN_STACK_HARDWARE_PASS')
print('STAGE28E_E3_MAIN_STACK_SAFE_FAKE_LOCKED_PASS')
PY
